insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('ce000000-0000-0000-0000-000000000001', 'ukmla', '8c513a65-3315-4909-bfb9-a7c57e4f4f7e',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('ce000000-0000-0000-0000-000000000001', 'A', 'Refer urgently via the 2-week-wait suspected cancer pathway for colonoscopy', true, 'Correct. Change in bowel habit plus PR bleeding plus weight loss plus iron-deficiency anaemia in a woman over 60 meets NICE NG12 criteria for suspected colorectal cancer; urgent 2WW referral for colonoscopy is required regardless of examination findings.', 1),
('ce000000-0000-0000-0000-000000000001', 'B', 'Reassure and review in 6 weeks', false, 'Ruled out because this combination of red-flag symptoms requires urgent investigation, not a delayed review.', 2),
('ce000000-0000-0000-0000-000000000001', 'C', 'Start oral iron and recheck FBC in 3 months without referral', false, 'Ruled out because correcting the anaemia without investigating its cause risks missing an underlying malignancy.', 3),
('ce000000-0000-0000-0000-000000000001', 'D', 'Arrange routine (non-urgent) outpatient gastroenterology referral', false, 'Ruled out because routine referral underestimates the urgency; red-flag features mandate 2WW referral.', 4),
('ce000000-0000-0000-0000-000000000001', 'E', 'Prescribe loperamide for symptomatic relief and discharge', false, 'Ruled out because symptomatic treatment without addressing the likely underlying malignancy is unsafe.', 5),
('ce000000-0000-0000-0000-000000000002', 'A', 'Reassure that a single episode is likely benign atrophic bleeding and discharge', false, 'Ruled out because postmenopausal bleeding, however minor, is never assumed benign without investigation.', 1),
('ce000000-0000-0000-0000-000000000002', 'B', 'Arrange routine gynaecology referral in 3 months', false, 'Ruled out because this delay is unsafe for postmenopausal bleeding.', 2),
('ce000000-0000-0000-0000-000000000002', 'C', 'Repeat cervical smear only', false, 'Ruled out because this is the wrong test and does not assess the endometrium, the likely source.', 3),
('ce000000-0000-0000-0000-000000000002', 'D', 'Start topical vaginal oestrogen and review in 6 weeks', false, 'Ruled out because treating symptomatically without excluding cancer first is unsafe.', 4),
('ce000000-0000-0000-0000-000000000002', 'E', 'Urgent 2-week-wait referral for transvaginal ultrasound and endometrial assessment', true, 'Correct. Any postmenopausal bleeding warrants urgent 2WW referral to exclude endometrial cancer, particularly given the raised risk from obesity and diabetes.', 5),
('ce000000-0000-0000-0000-000000000003', 'A', 'Barium swallow as first-line investigation', false, 'Ruled out because OGD is preferred first-line as it allows direct visualisation and biopsy.', 1),
('ce000000-0000-0000-0000-000000000003', 'B', 'Urgent (2-week-wait) upper GI endoscopy', true, 'Correct. Progressive dysphagia with weight loss in an older patient with a heavy smoking and alcohol history is classic for oesophageal cancer and requires urgent OGD.', 2),
('ce000000-0000-0000-0000-000000000003', 'C', 'Trial of proton pump inhibitor for 8 weeks then review', false, 'Ruled out because this delays diagnosis of red-flag dysphagia.', 3),
('ce000000-0000-0000-0000-000000000003', 'D', 'Reassure and advise smaller, softer meals', false, 'Ruled out because symptomatic advice without investigation is unsafe given red-flag features.', 4),
('ce000000-0000-0000-0000-000000000003', 'E', 'Routine outpatient gastroenterology referral in 6 weeks', false, 'Ruled out because this is too slow for a red-flag presentation.', 5),
('ce000000-0000-0000-0000-000000000004', 'A', 'Treat empirically for urinary tract infection with antibiotics', false, 'Ruled out because there is no evidence of infection and empirical treatment is inappropriate.', 1),
('ce000000-0000-0000-0000-000000000004', 'B', 'Reassure as likely benign and repeat urinalysis in 3 months', false, 'Ruled out because this represents an unsafe delay for a red-flag symptom.', 2),
('ce000000-0000-0000-0000-000000000004', 'C', 'Urgent 2-week-wait referral to urology for cystoscopy and imaging', true, 'Correct. Painless visible haematuria in anyone over 45 mandates urgent urological referral to exclude bladder or renal cancer.', 3),
('ce000000-0000-0000-0000-000000000004', 'D', 'Arrange routine outpatient urology referral', false, 'Ruled out because this is too slow for painless visible haematuria.', 4),
('ce000000-0000-0000-0000-000000000004', 'E', 'Advise increased fluid intake and review only if bleeding recurs', false, 'Ruled out because this is an unsafe delay in investigating a red-flag symptom.', 5),
('ce000000-0000-0000-0000-000000000005', 'A', 'Reassure and advise re-examination after her next menstrual period', false, 'Ruled out because these hard, irregular features are already concerning and should not be observed through a cycle.', 1),
('ce000000-0000-0000-0000-000000000005', 'B', 'Arrange routine breast clinic referral within 12 weeks', false, 'Ruled out because this is too slow for a suspicious lump.', 2),
('ce000000-0000-0000-0000-000000000005', 'C', 'Request only a breast ultrasound in primary care before referral', false, 'Ruled out because triple assessment should be completed in secondary care, not piecemeal in primary care.', 3),
('ce000000-0000-0000-0000-000000000005', 'D', 'Urgent 2-week-wait referral to the breast clinic for triple assessment', true, 'Correct. A discrete, hard, irregular breast lump in a woman over 30 is a red flag requiring urgent referral for clinical examination, imaging, and biopsy.', 4),
('ce000000-0000-0000-0000-000000000005', 'E', 'Prescribe evening primrose oil and review in 3 months', false, 'Ruled out because this is appropriate only for benign cyclical breast pain, not a suspicious lump.', 5),
('ce000000-0000-0000-0000-000000000006', 'A', 'Arrange a chest X-ray only and reassure if normal', false, 'Ruled out because a chest X-ray should be considered alongside, not instead of, urgent ENT referral.', 1),
('ce000000-0000-0000-0000-000000000006', 'B', 'Prescribe a proton pump inhibitor for presumed laryngopharyngeal reflux and review in 8 weeks', false, 'Ruled out because this delays diagnosis of a red-flag symptom.', 2),
('ce000000-0000-0000-0000-000000000006', 'C', 'Reassure that a normal neck examination excludes malignancy', false, 'Ruled out because early laryngeal cancer often has no palpable neck findings.', 3),
('ce000000-0000-0000-0000-000000000006', 'D', 'Refer routinely to speech and language therapy for voice rest advice', false, 'Ruled out because this is inappropriate without first excluding malignancy.', 4),
('ce000000-0000-0000-0000-000000000006', 'E', 'Urgent 2-week-wait referral to ENT for laryngoscopy', true, 'Correct. Persistent hoarseness lasting more than 3 weeks in a smoker warrants urgent ENT referral to exclude laryngeal cancer.', 5),
('ce000000-0000-0000-0000-000000000007', 'A', 'Start oral ferrous sulfate and recheck bloods in 3 months', false, 'Ruled out because treating anaemia without investigating unexplained IDA in this demographic risks missing cancer.', 1),
('ce000000-0000-0000-0000-000000000007', 'B', 'Reassure as likely dietary deficiency and advise iron-rich diet', false, 'Ruled out because unexplained IDA in an older man is never assumed dietary until excluded.', 2),
('ce000000-0000-0000-0000-000000000007', 'C', 'Urgent 2-week-wait referral for colonoscopy (with consideration of upper GI investigation)', true, 'Correct. Unexplained iron-deficiency anaemia in a man of any age warrants urgent investigation to exclude occult GI malignancy, most commonly colorectal.', 3),
('ce000000-0000-0000-0000-000000000007', 'D', 'Arrange routine gastroenterology outpatient referral', false, 'Ruled out because this is too slow for a red-flag finding.', 4),
('ce000000-0000-0000-0000-000000000007', 'E', 'Request only a faecal immunochemical test (FIT) and manage based on result alone', false, 'Ruled out because FIT is used in screening/lower-risk pathways, not as a substitute for urgent referral once unexplained IDA is confirmed in this risk group.', 5),
('ce000000-0000-0000-0000-000000000008', 'A', 'Reassure that the history of trauma explains the finding and review in 6 weeks', false, 'Ruled out because trauma commonly prompts self-examination that reveals a pre-existing mass; trauma itself rarely causes a firm irregular intratesticular lump.', 1),
('ce000000-0000-0000-0000-000000000008', 'B', 'Urgent (same-day/2-week-wait) referral to urology for scrotal ultrasound', true, 'Correct. A painless, firm, irregular intratesticular mass in a young man is highly suspicious for testicular cancer and requires urgent urological assessment and ultrasound.', 2),
('ce000000-0000-0000-0000-000000000008', 'C', 'Arrange routine urology outpatient referral within 12 weeks', false, 'Ruled out because this is too slow for a red-flag finding.', 3),
('ce000000-0000-0000-0000-000000000008', 'D', 'Prescribe a course of antibiotics for presumed epididymo-orchitis', false, 'Ruled out because there is no tenderness, fever, or urinary symptoms to support infection.', 4),
('ce000000-0000-0000-0000-000000000008', 'E', 'Advise scrotal support and review only if the lump enlarges', false, 'Ruled out because this represents an unsafe delay for a suspicious mass.', 5),
('ce000000-0000-0000-0000-000000000009', 'A', 'Urgent 2-week-wait referral to dermatology for suspected melanoma', true, 'Correct. A pigmented lesion with a high weighted 7-point checklist score (change in size, irregular border, variable colour) should be referred urgently to exclude melanoma.', 1),
('ce000000-0000-0000-0000-000000000009', 'B', 'Reassure and advise routine review by GP in 6 months to monitor for change', false, 'Ruled out because this is an unsafe delay when features are already concerning.', 2),
('ce000000-0000-0000-0000-000000000009', 'C', 'Arrange a routine dermatology outpatient appointment', false, 'Ruled out because this is too slow for a suspicious pigmented lesion.', 3),
('ce000000-0000-0000-0000-000000000009', 'D', 'Perform a shave biopsy in primary care to confirm diagnosis before referral', false, 'Ruled out because incomplete/shave biopsy risks incorrect staging and is not recommended for suspected melanoma.', 4),
('ce000000-0000-0000-0000-000000000009', 'E', 'Prescribe a topical steroid and review in 4 weeks', false, 'Ruled out because this is inappropriate and unsafe for a suspicious pigmented lesion.', 5),
('ce000000-0000-0000-0000-000000000010', 'A', 'Reassure and treat empirically for a chest infection with amoxicillin', false, 'Ruled out because these red flags require urgent investigation rather than empirical treatment alone.', 1),
('ce000000-0000-0000-0000-000000000010', 'B', 'Arrange routine chest X-ray within 6 weeks', false, 'Ruled out because imaging needs to be urgent (within 2 weeks) given the red flags.', 2),
('ce000000-0000-0000-0000-000000000010', 'C', 'Refer routinely to respiratory outpatients without imaging', false, 'Ruled out because a chest X-ray should be arranged urgently first or alongside referral.', 3),
('ce000000-0000-0000-0000-000000000010', 'D', 'Urgent chest X-ray within 2 weeks, with 2-week-wait referral for suspected lung cancer if imaging is suspicious or risk factors persist', true, 'Correct. Haemoptysis with a significant smoking history and weight loss in a patient over 40 requires an urgent chest X-ray as the first step, with urgent referral if abnormal or clinical suspicion remains high.', 4),
('ce000000-0000-0000-0000-000000000010', 'E', 'Reassure that a normal chest examination excludes malignancy', false, 'Ruled out because early lung cancer frequently has a normal chest examination.', 5),
('ce000000-0000-0000-0000-000000000011', 'A', 'Baseline pulmonary function tests', false, 'Ruled out because this is more relevant to bleomycin, not the principal toxicity concern with anthracyclines.', 1),
('ce000000-0000-0000-0000-000000000011', 'B', 'Baseline echocardiogram to assess left ventricular ejection fraction', true, 'Correct. Anthracyclines such as doxorubicin cause dose-dependent, potentially irreversible cardiotoxicity; baseline and interval LVEF assessment is required to monitor for decline during treatment.', 2),
('ce000000-0000-0000-0000-000000000011', 'C', 'Baseline audiometry', false, 'Ruled out because this is relevant to platinum agents (ototoxicity), not anthracyclines.', 3),
('ce000000-0000-0000-0000-000000000011', 'D', 'Baseline nerve conduction studies', false, 'Ruled out because this is relevant to vinca alkaloid/platinum-induced peripheral neuropathy, not the primary anthracycline concern.', 4),
('ce000000-0000-0000-0000-000000000011', 'E', 'Baseline renal ultrasound', false, 'Ruled out because this is not the principal monitoring requirement for anthracycline cardiotoxicity.', 5),
('ce000000-0000-0000-0000-000000000012', 'A', 'To prevent cisplatin-induced peripheral neuropathy', false, 'Ruled out because hydration does not prevent neurotoxicity, which is dose-related and managed differently.', 1),
('ce000000-0000-0000-0000-000000000012', 'B', 'To reduce the risk of cisplatin-induced cardiomyopathy', false, 'Ruled out because cardiotoxicity is not the primary concern with cisplatin; nephrotoxicity and ototoxicity are the classic dose-limiting toxicities.', 2),
('ce000000-0000-0000-0000-000000000012', 'C', 'To reduce the risk of haemorrhagic cystitis', false, 'Ruled out because haemorrhagic cystitis is classically associated with cyclophosphamide/ifosfamide, not the main reason for cisplatin hydration protocols.', 3),
('ce000000-0000-0000-0000-000000000012', 'D', 'To reduce the risk of cisplatin-induced nephrotoxicity by maintaining renal perfusion and urine output', true, 'Correct. Cisplatin is directly nephrotoxic (proximal tubular damage); vigorous IV hydration before and after administration reduces the risk and severity of acute kidney injury.', 4),
('ce000000-0000-0000-0000-000000000012', 'E', 'To prevent bleomycin-type pulmonary fibrosis', false, $x$Ruled out because this is unrelated to cisplatin's toxicity profile.$x$, 5),
('ce000000-0000-0000-0000-000000000013', 'A', 'Cisplatin-induced ototoxicity', false, 'Ruled out because this does not cause limb weakness or absent reflexes; it presents with hearing loss/tinnitus.', 1),
('ce000000-0000-0000-0000-000000000013', 'B', 'Methotrexate-induced mucositis', false, 'Ruled out because this causes oral/GI mucosal ulceration, not peripheral neuropathy.', 2),
('ce000000-0000-0000-0000-000000000013', 'C', 'Doxorubicin-induced cardiomyopathy', false, 'Ruled out because this presents with signs of heart failure, not peripheral neuropathy.', 3),
('ce000000-0000-0000-0000-000000000013', 'D', 'Bleomycin-induced pulmonary fibrosis', false, 'Ruled out because this presents with respiratory symptoms, not peripheral neuropathy.', 4),
('ce000000-0000-0000-0000-000000000013', 'E', 'Vincristine-induced peripheral neuropathy', true, 'Correct. Vincristine classically causes a dose-dependent, predominantly sensorimotor peripheral neuropathy with distal weakness and loss of deep tendon reflexes; it is one of its principal dose-limiting toxicities.', 5),
('ce000000-0000-0000-0000-000000000014', 'A', 'Minimise inspired oxygen concentration to the lowest level needed to maintain adequate saturations', true, 'Correct. Bleomycin causes dose-dependent pulmonary fibrosis, and patients who have received it are at risk of triggering or worsening lung injury with high concentrations of supplemental oxygen, even long after treatment; oxygen should be titrated to the minimum required.', 1),
('ce000000-0000-0000-0000-000000000014', 'B', 'Administer high-flow 100% oxygen throughout the procedure to prevent hypoxia', false, 'Ruled out because this is precisely the exposure that risks precipitating bleomycin-induced pulmonary toxicity.', 2),
('ce000000-0000-0000-0000-000000000014', 'C', 'Withhold all supplemental oxygen regardless of saturation', false, 'Ruled out because oxygen should still be given if genuinely needed, at the lowest effective concentration, not withheld entirely if the patient is hypoxic.', 3),
('ce000000-0000-0000-0000-000000000014', 'D', 'No special precaution is needed as bleomycin does not affect the lungs', false, 'Ruled out because bleomycin is well recognised for causing pulmonary toxicity.', 4),
('ce000000-0000-0000-0000-000000000014', 'E', 'Arrange prophylactic antibiotics to prevent pulmonary fibrosis', false, 'Ruled out because antibiotics do not prevent or treat bleomycin lung toxicity, which is a fibrotic, not infective, process.', 5),
('ce000000-0000-0000-0000-000000000015', 'A', 'Neutropenic sepsis', false, 'Ruled out because there is no fever or systemic signs of sepsis; this is a localised skin toxicity.', 1),
('ce000000-0000-0000-0000-000000000015', 'B', 'Anaphylaxis to capecitabine', false, 'Ruled out because there are no features of an acute hypersensitivity reaction such as urticaria, angioedema, or hypotension.', 2),
('ce000000-0000-0000-0000-000000000015', 'C', 'Hand-foot syndrome (palmar-plantar erythrodysaesthesia)', true, 'Correct. This is a well-recognised toxicity of capecitabine (and other fluoropyrimidines), presenting with painful erythema, swelling, and desquamation of the palms and soles.', 3),
('ce000000-0000-0000-0000-000000000015', 'D', 'Cellulitis of both hands and feet', false, 'Ruled out because bilateral symmetrical involvement without fever or systemic illness is more consistent with a drug toxicity than infection.', 4),
('ce000000-0000-0000-0000-000000000015', 'E', 'Digital ischaemia from vasospasm', false, 'Ruled out because erythema, swelling, and desquamation are not consistent with ischaemic changes.', 5),
('ce000000-0000-0000-0000-000000000016', 'A', 'Reassure that vaginal bleeding is an expected effect of tamoxifen and no investigation is needed', false, $x$Ruled out because postmenopausal bleeding always requires investigation, especially given tamoxifen's known endometrial risk.$x$, 1),
('ce000000-0000-0000-0000-000000000016', 'B', 'Stop tamoxifen immediately and switch to an aromatase inhibitor without further investigation', false, 'Ruled out because the bleeding itself must be investigated first before changing treatment.', 2),
('ce000000-0000-0000-0000-000000000016', 'C', 'Arrange a routine gynaecology referral in 3 months', false, 'Ruled out because this is too slow for postmenopausal bleeding.', 3),
('ce000000-0000-0000-0000-000000000016', 'D', 'Urgent referral for transvaginal ultrasound and endometrial assessment to exclude endometrial cancer', true, 'Correct. Tamoxifen has an oestrogenic effect on the endometrium and increases the risk of endometrial hyperplasia and cancer; any postmenopausal bleeding on tamoxifen requires urgent gynaecological investigation.', 4),
('ce000000-0000-0000-0000-000000000016', 'E', 'Treat with progestogen to suppress bleeding', false, 'Ruled out because treating symptomatically without excluding malignancy is unsafe.', 5),
('ce000000-0000-0000-0000-000000000017', 'A', 'Trastuzumab commonly causes irreversible pulmonary fibrosis', false, 'Ruled out because this is a recognised toxicity of bleomycin, not trastuzumab.', 1),
('ce000000-0000-0000-0000-000000000017', 'B', 'Trastuzumab commonly causes peripheral neuropathy requiring nerve conduction monitoring', false, 'Ruled out because peripheral neuropathy is more typical of taxanes, platinum agents, and vinca alkaloids.', 2),
('ce000000-0000-0000-0000-000000000017', 'C', 'Trastuzumab commonly causes nephrotoxicity requiring renal monitoring', false, 'Ruled out because cisplatin, not trastuzumab, is the classic nephrotoxic chemotherapy agent.', 3),
('ce000000-0000-0000-0000-000000000017', 'D', 'Trastuzumab commonly causes ototoxicity requiring audiometry', false, 'Ruled out because ototoxicity is associated with platinum agents, not trastuzumab.', 4),
('ce000000-0000-0000-0000-000000000017', 'E', 'Trastuzumab can cause reversible left ventricular dysfunction and heart failure, requiring LVEF monitoring', true, 'Correct. Trastuzumab is associated with cardiotoxicity (typically a reversible reduction in LVEF), with risk increased by prior anthracycline exposure; regular LVEF monitoring is required throughout treatment.', 5),
('ce000000-0000-0000-0000-000000000018', 'A', 'Mesna', false, 'Ruled out because mesna is used to prevent haemorrhagic cystitis from cyclophosphamide/ifosfamide, not methotrexate toxicity.', 1),
('ce000000-0000-0000-0000-000000000018', 'B', 'Desferrioxamine', false, 'Ruled out because this is an iron chelator used in iron overload/poisoning, unrelated to methotrexate rescue.', 2),
('ce000000-0000-0000-0000-000000000018', 'C', 'Folinic acid (calcium folinate) rescue', true, 'Correct. Folinic acid bypasses the block on dihydrofolate reductase caused by methotrexate, restoring folate metabolism in normal cells and reducing toxicity (mucositis, myelosuppression), while methotrexate levels are monitored to guide dosing and timing.', 3),
('ce000000-0000-0000-0000-000000000018', 'D', 'N-acetylcysteine', false, 'Ruled out because this is used in paracetamol overdose, not methotrexate toxicity.', 4),
('ce000000-0000-0000-0000-000000000018', 'E', 'Naloxone', false, 'Ruled out because this is an opioid antagonist, unrelated to methotrexate.', 5),
('ce000000-0000-0000-0000-000000000019', 'A', 'Infective gastroenteritis', false, 'Ruled out because stool culture is negative and the temporal association with immunotherapy makes an immune-related cause more likely.', 1),
('ce000000-0000-0000-0000-000000000019', 'B', 'Immune checkpoint inhibitor-induced colitis', true, 'Correct. Checkpoint inhibitors can cause immune-related adverse events affecting any organ, with colitis being one of the most common gastrointestinal manifestations; it requires prompt recognition as it can progress to severe, life-threatening colitis.', 2),
('ce000000-0000-0000-0000-000000000019', 'C', 'Irritable bowel syndrome', false, 'Ruled out because new-onset severe diarrhoea in a patient on immunotherapy should not be attributed to a functional diagnosis without excluding drug-related colitis.', 3),
('ce000000-0000-0000-0000-000000000019', 'D', 'Chemotherapy-induced mucositis', false, 'Ruled out because he is on immunotherapy, not cytotoxic chemotherapy, and mucositis does not typically present as high-frequency watery diarrhoea of this severity.', 4),
('ce000000-0000-0000-0000-000000000019', 'E', 'Malignant bowel obstruction', false, 'Ruled out because obstruction typically presents with absolute constipation, distension, and vomiting, not high-frequency watery diarrhoea.', 5),
('ce000000-0000-0000-0000-000000000020', 'A', 'Stop the infusion immediately, aspirate any residual drug from the cannula, and follow the extravasation protocol before removing the line', true, 'Correct. Suspected extravasation of a vesicant chemotherapy agent requires immediate cessation of the infusion, aspiration of residual drug, and prompt management per local extravasation protocol to minimise tissue damage.', 1),
('ce000000-0000-0000-0000-000000000020', 'B', 'Increase the infusion rate to flush the drug through more quickly', false, 'Ruled out because this worsens tissue injury by pushing more vesicant into the extravascular space.', 2),
('ce000000-0000-0000-0000-000000000020', 'C', 'Continue the infusion as the cannula appears to still be patent', false, 'Ruled out because continuing risks severe local tissue necrosis.', 3),
('ce000000-0000-0000-0000-000000000020', 'D', 'Apply a warm compress and continue the infusion via the same cannula', false, 'Ruled out because the infusion must be stopped first, and the type of compress used is agent-specific.', 4),
('ce000000-0000-0000-0000-000000000020', 'E', 'Remove the cannula immediately without aspirating and apply firm pressure', false, 'Ruled out because residual drug should be aspirated before removal where possible to reduce the volume of vesicant left in the tissue.', 5),
('ce000000-0000-0000-0000-000000000021', 'A', 'Mastitis', false, 'Ruled out because this typically presents acutely with pain, erythema, and fever, often in lactating women, not painless skin retraction over weeks.', 1),
('ce000000-0000-0000-0000-000000000021', 'B', 'Fibroadenoma', false, $x$Ruled out because this presents as a discrete, mobile, benign lump, not with skin dimpling or peau d'orange.$x$, 2),
('ce000000-0000-0000-0000-000000000021', 'C', 'Fat necrosis', false, $x$Ruled out because this usually follows trauma or surgery and presents as a firm lump, not typically with diffuse peau d'orange change.$x$, 3),
('ce000000-0000-0000-0000-000000000021', 'D', 'Locally advanced breast cancer with skin/lymphatic involvement', true, $x$Correct. Skin dimpling, nipple retraction, and peau d'orange (from dermal lymphatic obstruction) are classic signs of underlying breast malignancy invading the skin/lymphatics, even without a palpable discrete lump.$x$, 4),
('ce000000-0000-0000-0000-000000000021', 'E', 'Duct ectasia', false, $x$Ruled out because this presents with nipple discharge and a subareolar mass or tenderness, not skin dimpling or peau d'orange.$x$, 5),
('ce000000-0000-0000-0000-000000000022', 'A', $x$Bell's palsy$x$, false, 'Ruled out because this causes facial weakness due to facial nerve palsy, not ptosis/miosis, and is unrelated to sympathetic chain involvement.', 1),
('ce000000-0000-0000-0000-000000000022', 'B', 'Myasthenia gravis', false, 'Ruled out because this causes fatigable ptosis (often bilateral) without miosis or anhidrosis, and would not explain the apical opacity or clubbing.', 2),
('ce000000-0000-0000-0000-000000000022', 'C', $x$Pancoast tumour (apical lung cancer) causing Horner's syndrome$x$, true, $x$Correct. An apical lung tumour can invade the sympathetic chain, producing Horner's syndrome (ptosis, miosis, anhidrosis) along with shoulder/arm pain from brachial plexus involvement; clubbing further supports underlying lung malignancy.$x$, 3),
('ce000000-0000-0000-0000-000000000022', 'D', 'Cluster headache', false, 'Ruled out because this causes unilateral severe headache with autonomic features but is not associated with clubbing or an apical lung mass.', 4),
('ce000000-0000-0000-0000-000000000022', 'E', 'Cervical rib syndrome (thoracic outlet syndrome)', false, $x$Ruled out because this can cause arm symptoms from neurovascular compression but does not typically cause Horner's syndrome or an apical opacity with clubbing.$x$, 5),
('ce000000-0000-0000-0000-000000000023', 'A', 'Right-sided colorectal cancer', false, 'Ruled out because right-sided tumours more typically present with occult bleeding and iron-deficiency anaemia rather than overt change in bowel habit, due to the wider caecal lumen and more liquid stool.', 1),
('ce000000-0000-0000-0000-000000000023', 'B', 'Diverticular disease', false, 'Ruled out because although it can cause bleeding and altered bowel habit, it is less likely to explain progressive weight loss, and malignancy must still be excluded.', 2),
('ce000000-0000-0000-0000-000000000023', 'C', 'Irritable bowel syndrome', false, 'Ruled out because this does not cause weight loss or rectal bleeding and would not be diagnosed without excluding organic pathology in this age group.', 3),
('ce000000-0000-0000-0000-000000000023', 'D', 'Haemorrhoids', false, 'Ruled out because these can cause rectal bleeding but would not explain systemic weight loss or a change in bowel habit of this nature.', 4),
('ce000000-0000-0000-0000-000000000023', 'E', 'Left-sided colorectal cancer', true, 'Correct. A change in bowel habit, rectal bleeding, and weight loss in an older patient is characteristic of left-sided colorectal cancer, which tends to present with obstructive symptoms due to the narrower lumen and more solid stool on that side.', 5),
('ce000000-0000-0000-0000-000000000024', 'A', 'Mechanical lower back pain from degenerative disc disease', false, 'Ruled out because the markedly raised PSA and nodular prostate make metastatic disease the more likely and more urgent explanation, which must be excluded.', 1),
('ce000000-0000-0000-0000-000000000024', 'B', 'Bone metastases from prostate cancer', true, 'Correct. Prostate cancer classically metastasises to bone, particularly the axial skeleton; new persistent back pain with a markedly elevated PSA and abnormal prostate examination should raise strong suspicion of metastatic bone disease.', 2),
('ce000000-0000-0000-0000-000000000024', 'C', 'Osteoporotic vertebral fracture', false, 'Ruled out because this does not explain the striking PSA elevation and abnormal prostate findings, which point towards malignancy.', 3),
('ce000000-0000-0000-0000-000000000024', 'D', 'Renal colic', false, 'Ruled out because this does not fit with persistent, rather than colicky, back pain and does not explain the prostate/PSA findings.', 4),
('ce000000-0000-0000-0000-000000000024', 'E', 'Pyelonephritis', false, 'Ruled out because this would typically present with fever, loin pain, and urinary infection symptoms, not a chronic pattern with grossly elevated PSA.', 5),
('ce000000-0000-0000-0000-000000000025', 'A', 'Urgent 2-week-wait upper GI endoscopy', true, 'Correct. New dyspepsia with weight loss and vomiting in a patient over 55 is a red-flag combination requiring urgent upper GI endoscopy to exclude gastric or oesophageal cancer.', 1),
('ce000000-0000-0000-0000-000000000025', 'B', 'Trial of a proton pump inhibitor for 8 weeks before considering endoscopy', false, 'Ruled out because PPI trials are appropriate for uncomplicated dyspepsia without red flags, not when weight loss and vomiting are present.', 2),
('ce000000-0000-0000-0000-000000000025', 'C', 'Test for Helicobacter pylori and treat if positive, without endoscopy', false, 'Ruled out because red-flag features mean endoscopy is needed regardless of H. pylori status.', 3),
('ce000000-0000-0000-0000-000000000025', 'D', 'Reassure and advise dietary modification with review in 3 months', false, 'Ruled out because this represents an unsafe delay with red-flag symptoms.', 4),
('ce000000-0000-0000-0000-000000000025', 'E', 'Arrange routine gastroenterology outpatient referral', false, 'Ruled out because this is too slow given the red flags.', 5),
('ce000000-0000-0000-0000-000000000026', 'A', 'Acute cholecystitis', false, 'Ruled out because this typically causes right upper quadrant pain, fever, and a tender gallbladder, not painless jaundice with a non-tender mass.', 1),
('ce000000-0000-0000-0000-000000000026', 'B', 'Choledocholithiasis (common bile duct gallstone)', false, 'Ruled out because this classically causes painful, colicky obstructive jaundice, and a palpable gallbladder with painless jaundice is unlikely to be due to gallstones.', 2),
('ce000000-0000-0000-0000-000000000026', 'C', 'Carcinoma of the head of the pancreas', true, $x$Correct. Painless obstructive jaundice with a palpable, non-tender gallbladder (Courvoisier's sign) strongly suggests malignant biliary obstruction, most commonly from a pancreatic head tumour compressing the common bile duct.$x$, 3),
('ce000000-0000-0000-0000-000000000026', 'D', 'Viral hepatitis', false, 'Ruled out because this typically causes tender hepatomegaly and a systemic prodrome, not a palpable gallbladder or obstructive-pattern painless jaundice with weight loss.', 4),
('ce000000-0000-0000-0000-000000000026', 'E', 'Haemolytic anaemia', false, 'Ruled out because this causes unconjugated hyperbilirubinaemia without pale stools or dark urine, and does not cause a palpable gallbladder.', 5),
('ce000000-0000-0000-0000-000000000027', 'A', 'Serum PSA', false, 'Ruled out because this is a marker used in prostate cancer in men, irrelevant here.', 1),
('ce000000-0000-0000-0000-000000000027', 'B', 'Serum CA125', true, 'Correct. Persistent bloating, early satiety, urinary symptoms, and abdominal distension in a woman over 50 are recognised red-flag symptoms for ovarian cancer; serum CA125 is the recommended first-line investigation, with pelvic ultrasound if elevated.', 2),
('ce000000-0000-0000-0000-000000000027', 'C', 'Serum AFP alone', false, 'Ruled out because this is more relevant to hepatocellular carcinoma or certain germ cell tumours, not the first-line test here.', 3),
('ce000000-0000-0000-0000-000000000027', 'D', 'Colonoscopy as the first investigation', false, 'Ruled out because this constellation of symptoms should first prompt CA125/pelvic assessment for ovarian pathology.', 4),
('ce000000-0000-0000-0000-000000000027', 'E', 'Reassure and manage as irritable bowel syndrome, given the vague symptoms', false, 'Ruled out because new onset of these symptoms in a woman over 50 should not be assumed IBS without investigation.', 5),
('ce000000-0000-0000-0000-000000000028', 'A', 'Renal cell carcinoma', true, 'Correct. The classic triad of haematuria, flank pain, and a palpable abdominal mass, combined with a new left-sided varicocele from renal vein compression, is characteristic of renal cell carcinoma.', 1),
('ce000000-0000-0000-0000-000000000028', 'B', 'Testicular torsion', false, 'Ruled out because this causes acute severe testicular pain, not a slowly developing, non-tender varicocele with a flank mass.', 2),
('ce000000-0000-0000-0000-000000000028', 'C', 'Epididymal cyst', false, 'Ruled out because this presents as a small, cystic, separate scrotal lump, not a varicocele, and does not explain the flank mass or haematuria.', 3),
('ce000000-0000-0000-0000-000000000028', 'D', 'Benign varicocele unrelated to any underlying pathology', false, 'Ruled out because a new varicocele that does not empty on lying flat, especially left-sided in an older man, should raise suspicion of underlying renal or retroperitoneal pathology.', 4),
('ce000000-0000-0000-0000-000000000028', 'E', 'Renal calculus', false, 'Ruled out because this typically causes acute colicky pain, not a palpable mass with painless haematuria and varicocele.', 5),
('ce000000-0000-0000-0000-000000000029', 'A', 'Urinary tract infection', false, 'Ruled out because there are no leucocytes, nitrites, dysuria, or fever to support infection.', 1),
('ce000000-0000-0000-0000-000000000029', 'B', 'Benign prostatic hyperplasia', false, 'Ruled out because this can cause urinary symptoms but does not typically cause visible haematuria as the primary presenting feature.', 2),
('ce000000-0000-0000-0000-000000000029', 'C', 'Renal calculus', false, 'Ruled out because this usually presents with acute colicky pain, not painless recurrent haematuria.', 3),
('ce000000-0000-0000-0000-000000000029', 'D', 'Transitional cell carcinoma of the bladder', true, 'Correct. Painless visible haematuria in an older adult, especially with occupational exposure to aromatic amines, is a classic presentation of bladder (urothelial) cancer.', 4),
('ce000000-0000-0000-0000-000000000029', 'E', 'Nephritic syndrome (glomerulonephritis)', false, 'Ruled out because this typically causes non-visible or smoky haematuria with proteinuria, hypertension, and oedema, not isolated episodes of painless visible haematuria.', 5),
('ce000000-0000-0000-0000-000000000030', 'A', 'Reactive lymphadenopathy from a viral infection', false, 'Ruled out because this would not explain the ulcerated tonsillar lesion, weight loss, or a fixed node persisting over 2 months.', 1),
('ce000000-0000-0000-0000-000000000030', 'B', 'Infectious mononucleosis', false, 'Ruled out because this typically causes bilateral tender lymphadenopathy with pharyngitis in younger patients, not an ulcerated lesion with a fixed unilateral node and weight loss in this age group.', 2),
('ce000000-0000-0000-0000-000000000030', 'C', 'Branchial cyst', false, 'Ruled out because this presents as a soft, fluctuant lateral neck swelling typically in younger adults, not a firm fixed node with a mucosal lesion.', 3),
('ce000000-0000-0000-0000-000000000030', 'D', 'Thyroid goitre', false, 'Ruled out because this presents as a midline/anterior neck swelling that moves on swallowing, not a lateral neck node, and would not explain the tonsillar ulcer.', 4),
('ce000000-0000-0000-0000-000000000030', 'E', 'Squamous cell carcinoma of the oropharynx (tonsil) with cervical lymph node metastasis', true, 'Correct. A persistent ulcerated oropharyngeal lesion with an ipsilateral firm, fixed cervical lymph node, dysphagia, and weight loss in a patient with a heavy smoking/alcohol history is characteristic of oropharyngeal squamous cell carcinoma with nodal spread.', 5),
('ce000000-0000-0000-0000-000000000031', 'A', 'Wait for blood culture results before starting antibiotics to avoid masking the causative organism', false, 'Ruled out because this dangerous delay significantly increases mortality; empirical treatment must not be delayed for culture results.', 1),
('ce000000-0000-0000-0000-000000000031', 'B', 'Immediate empirical broad-spectrum intravenous antibiotics (e.g., piperacillin-tazobactam) within 1 hour, without waiting for culture results', true, 'Correct. Neutropenic sepsis is a medical emergency; broad-spectrum antibiotics must be started within 1 hour of presentation in any febrile neutropenic patient, as delay significantly increases mortality.', 2),
('ce000000-0000-0000-0000-000000000031', 'C', 'Give oral antibiotics and discharge with safety-netting advice if he feels well enough', false, 'Ruled out because febrile neutropenia after chemotherapy requires admission and IV antibiotics.', 3),
('ce000000-0000-0000-0000-000000000031', 'D', 'Administer granulocyte colony-stimulating factor (G-CSF) alone as the first step, without antibiotics', false, 'Ruled out because G-CSF may be considered as an adjunct in some cases, but antibiotics are the immediate priority and must not be delayed.', 4),
('ce000000-0000-0000-0000-000000000031', 'E', 'Arrange urgent CT chest/abdomen/pelvis before starting any treatment', false, 'Ruled out because imaging to look for a source should not delay life-saving empirical antibiotics.', 5),
('ce000000-0000-0000-0000-000000000032', 'A', 'Reassure and arrange outpatient physiotherapy for suspected musculoskeletal back pain', false, 'Ruled out because this presentation with neurological deficit and known metastatic disease is a red flag for cord compression, not simple back pain.', 1),
('ce000000-0000-0000-0000-000000000032', 'B', 'Arrange a routine outpatient MRI within 2 weeks', false, 'Ruled out because suspected MSCC requires MRI within 24 hours, not a routine outpatient timeframe.', 2),
('ce000000-0000-0000-0000-000000000032', 'C', 'Immediate high-dose dexamethasone and urgent whole-spine MRI within 24 hours', true, 'Correct. This presentation is highly suspicious for metastatic spinal cord compression, an oncological emergency requiring immediate high-dose corticosteroids and urgent MRI of the whole spine to confirm the level and guide treatment.', 3),
('ce000000-0000-0000-0000-000000000032', 'D', 'Start strong opioid analgesia only, and review in 48 hours', false, 'Ruled out because analgesia alone without steroids/imaging risks progression to irreversible paralysis.', 4),
('ce000000-0000-0000-0000-000000000032', 'E', 'Perform a lumbar puncture to assess for meningeal involvement', false, 'Ruled out because lumbar puncture is not indicated and is potentially hazardous in suspected cord compression.', 5),
('ce000000-0000-0000-0000-000000000033', 'A', 'Right heart failure', false, 'Ruled out because this would more typically cause peripheral (leg) oedema with a pulsatile JVP waveform, not dilated chest wall collateral veins in this pattern.', 1),
('ce000000-0000-0000-0000-000000000033', 'B', 'Anaphylaxis', false, 'Ruled out because this typically presents acutely with urticaria, wheeze, and hypotension, not a subacute picture over a week.', 2),
('ce000000-0000-0000-0000-000000000033', 'C', 'Nephrotic syndrome', false, 'Ruled out because this causes generalised oedema but not distended non-pulsatile neck veins or dilated chest wall collaterals.', 3),
('ce000000-0000-0000-0000-000000000033', 'D', 'Bilateral deep vein thrombosis of the arms', false, 'Ruled out because this would not explain facial plethora, headache worse on bending, or dilated chest wall collateral veins together.', 4),
('ce000000-0000-0000-0000-000000000033', 'E', 'Superior vena cava obstruction (SVCO)', true, 'Correct. Facial and upper limb swelling/plethora, headache worse on bending forward, and distended non-pulsatile neck and chest wall veins in a patient with a mediastinal malignancy are classic features of SVC obstruction from extrinsic tumour compression.', 5),
('ce000000-0000-0000-0000-000000000034', 'A', 'Tumour lysis syndrome', true, 'Correct. The combination of hyperkalaemia, hyperphosphataemia, hyperuricaemia, and hypocalcaemia with acute kidney injury shortly after starting chemotherapy for a high-grade, high-burden haematological malignancy is characteristic of tumour lysis syndrome.', 1),
('ce000000-0000-0000-0000-000000000034', 'B', 'Neutropenic sepsis', false, 'Ruled out because sepsis does not typically cause this specific metabolic pattern of hyperkalaemia, hyperphosphataemia, hyperuricaemia, and hypocalcaemia.', 2),
('ce000000-0000-0000-0000-000000000034', 'C', 'Acute adrenal insufficiency', false, 'Ruled out because this causes hyperkalaemia and hyponatraemia but not the characteristic hyperphosphataemia/hyperuricaemia pattern seen here.', 3),
('ce000000-0000-0000-0000-000000000034', 'D', 'Rhabdomyolysis unrelated to malignancy', false, 'Ruled out because although rhabdomyolysis also causes hyperkalaemia and hyperphosphataemia, the clinical context of bulky lymphoma and timing after chemotherapy make tumour lysis syndrome far more likely.', 4),
('ce000000-0000-0000-0000-000000000034', 'E', 'Chronic kidney disease progression', false, 'Ruled out because this does not explain the acute onset within 24 hours of chemotherapy or this specific combination of biochemical derangements.', 5),
('ce000000-0000-0000-0000-000000000035', 'A', 'Restrict fluids and give a loop diuretic to lower calcium', false, 'Ruled out because fluid restriction is inappropriate in a dehydrated hypercalcaemic patient, and loop diuretics are not first-line before adequate rehydration.', 1),
('ce000000-0000-0000-0000-000000000035', 'B', 'Give oral calcium supplementation to prevent tetany', false, 'Ruled out because calcium is already dangerously elevated; giving more calcium would worsen the crisis.', 2),
('ce000000-0000-0000-0000-000000000035', 'C', 'Start oral corticosteroids alone as first-line treatment', false, 'Ruled out because corticosteroids are not first-line for most solid tumour-associated hypercalcaemia; IV fluids plus bisphosphonate is standard first-line.', 3),
('ce000000-0000-0000-0000-000000000035', 'D', 'Aggressive intravenous 0.9% sodium chloride rehydration followed by an intravenous bisphosphonate', true, 'Correct. Severe hypercalcaemia of malignancy is a medical emergency; initial management is IV fluid rehydration followed promptly by an IV bisphosphonate to reduce osteoclast-mediated bone resorption.', 4),
('ce000000-0000-0000-0000-000000000035', 'E', 'Arrange outpatient endocrinology referral for delayed management', false, 'Ruled out because this calcium level with confusion and drowsiness requires urgent inpatient treatment.', 5),
('ce000000-0000-0000-0000-000000000036', 'A', 'Immediate whole brain radiotherapy without steroids', false, 'Ruled out because steroids should be started promptly to control oedema/symptoms while radiotherapy planning, which takes additional time, proceeds.', 1),
('ce000000-0000-0000-0000-000000000036', 'B', 'Mannitol as first-line long-term treatment', false, 'Ruled out because mannitol may be used in acute severe raised ICP crises but is not the standard first-line, sustained treatment for oedema around brain metastases.', 2),
('ce000000-0000-0000-0000-000000000036', 'C', 'High-dose dexamethasone', true, 'Correct. Corticosteroids rapidly reduce vasogenic oedema surrounding brain metastases, relieving symptoms of raised intracranial pressure while definitive treatment is arranged.', 3),
('ce000000-0000-0000-0000-000000000036', 'D', 'Lumbar puncture to relieve pressure', false, 'Ruled out because lumbar puncture is contraindicated with a mass lesion due to the risk of precipitating brain herniation.', 4),
('ce000000-0000-0000-0000-000000000036', 'E', 'Strong opioid analgesia alone for headache control', false, 'Ruled out because this does not address the underlying oedema/raised ICP or the ataxia and confusion.', 5),
('ce000000-0000-0000-0000-000000000037', 'A', 'Reassure and observe with routine hourly observations', false, 'Ruled out because this volume of haemoptysis with hypoxia and tachypnoea represents a life-threatening emergency requiring urgent escalation.', 1),
('ce000000-0000-0000-0000-000000000037', 'B', 'Give oral tranexamic acid and discharge home with outpatient follow-up', false, 'Ruled out because this is a life-threatening emergency requiring hospital admission and urgent intervention.', 2),
('ce000000-0000-0000-0000-000000000037', 'C', 'Arrange a routine outpatient CT chest in 1 week to investigate the bleeding source', false, 'Ruled out because urgent, not routine or delayed, imaging and intervention are required given the severity.', 3),
('ce000000-0000-0000-0000-000000000037', 'D', 'Perform immediate rigid bronchoscopy in the emergency department without senior input', false, 'Ruled out because definitive airway/bleeding management should involve urgent senior specialist input rather than being undertaken alone.', 4),
('ce000000-0000-0000-0000-000000000037', 'E', 'Position the patient with the bleeding (affected) lung side down, secure the airway, give high-flow oxygen, and urgently involve senior anaesthetic/respiratory/interventional radiology teams', true, 'Correct. Massive haemoptysis is an airway emergency; the immediate priority is protecting the airway and ventilation, with urgent senior/multidisciplinary escalation for definitive control.', 5),
('ce000000-0000-0000-0000-000000000038', 'A', 'Advise paracetamol and a GP review within the next few days if symptoms persist', false, 'Ruled out because this delay is unsafe; possible neutropenic sepsis requires immediate same-day assessment.', 1),
('ce000000-0000-0000-0000-000000000038', 'B', 'Advise her to attend the emergency department or oncology assessment unit immediately for urgent assessment and blood tests, as she requires exclusion of neutropenic sepsis', true, 'Correct. Any fever in a patient who has received chemotherapy within the past 6 weeks should be treated as possible neutropenic sepsis until proven otherwise, requiring immediate same-day hospital assessment and an urgent FBC.', 2),
('ce000000-0000-0000-0000-000000000038', 'C', 'Advise her to monitor her temperature at home and call back only if it exceeds 39C', false, 'Ruled out because a temperature of 38C or above post-chemotherapy is itself the threshold for urgent assessment.', 3),
('ce000000-0000-0000-0000-000000000038', 'D', 'Reassure that a mild fever is a normal, expected response to chemotherapy', false, 'Ruled out because fever after chemotherapy is never assumed benign until neutropenic sepsis has been excluded.', 4),
('ce000000-0000-0000-0000-000000000038', 'E', 'Arrange a routine face-to-face GP appointment for later in the week', false, 'Ruled out because this requires same-day emergency assessment, not a delayed GP appointment.', 5),
('ce000000-0000-0000-0000-000000000039', 'A', 'Syndrome of inappropriate antidiuretic hormone secretion (SIADH) from the small cell lung cancer', true, 'Correct. Small cell lung cancer is a classic cause of ectopic ADH secretion, leading to euvolaemic hyponatraemia with inappropriately concentrated urine and low serum osmolality.', 1),
('ce000000-0000-0000-0000-000000000039', 'B', 'Diabetes insipidus', false, 'Ruled out because this causes hypernatraemia with dilute urine due to lack of, or resistance to, ADH effect, the opposite pattern to that described.', 2),
('ce000000-0000-0000-0000-000000000039', 'C', $x$Addison's disease (primary adrenal insufficiency)$x$, false, 'Ruled out because this typically causes hyponatraemia with hyperkalaemia and hypovolaemia, not a euvolaemic picture with concentrated urine.', 3),
('ce000000-0000-0000-0000-000000000039', 'D', 'Excessive water intake (primary polydipsia)', false, 'Ruled out because he denies excessive fluid intake, and primary polydipsia typically causes dilute, not concentrated, urine.', 4),
('ce000000-0000-0000-0000-000000000039', 'E', 'Diuretic-induced hyponatraemia', false, 'Ruled out because no history of diuretic use is given, and this would require volume depletion, which is not present.', 5),
('ce000000-0000-0000-0000-000000000040', 'A', 'Immediate high-dose oral laxatives to relieve the obstruction', false, 'Ruled out because oral laxatives are inappropriate and potentially harmful in complete bowel obstruction with vomiting.', 1),
('ce000000-0000-0000-0000-000000000040', 'B', 'Discharge home with oral analgesia and outpatient review in 2 weeks', false, 'Ruled out because this presentation requires inpatient assessment and management, not discharge.', 2),
('ce000000-0000-0000-0000-000000000040', 'C', 'Insert a rectal tube and administer a phosphate enema as first-line treatment', false, 'Ruled out because this is not appropriate first-line management for suspected small bowel obstruction with vomiting.', 3),
('ce000000-0000-0000-0000-000000000040', 'D', 'Nasogastric tube insertion, intravenous fluid resuscitation, and urgent surgical/oncology assessment to determine suitability for further intervention', true, 'Correct. Malignant bowel obstruction requires initial conservative management (NG decompression and IV fluids) alongside urgent assessment to determine whether surgical intervention, stenting, or medical management is most appropriate.', 4),
('ce000000-0000-0000-0000-000000000040', 'E', 'Start oral chemotherapy immediately to shrink the tumour and relieve obstruction', false, 'Ruled out because oral chemotherapy would not be tolerated or effective as an immediate measure in this acute, vomiting, obstructed patient.', 5),
('ce000000-0000-0000-0000-000000000041', 'A', 'PSA', false, 'Ruled out because this is a marker for prostate pathology in men, not relevant to ovarian masses.', 1),
('ce000000-0000-0000-0000-000000000041', 'B', 'CEA', false, 'Ruled out because this is primarily used in colorectal cancer, not the standard marker for initial ovarian mass risk stratification.', 2),
('ce000000-0000-0000-0000-000000000041', 'C', 'Beta-hCG alone', false, 'Ruled out because this is more relevant to gestational trophoblastic disease or germ cell tumours in younger women, not the standard marker here.', 3),
('ce000000-0000-0000-0000-000000000041', 'D', 'AFP alone', false, 'Ruled out because this is relevant to certain germ cell tumours, not the standard first-line marker for this age group.', 4),
('ce000000-0000-0000-0000-000000000041', 'E', 'CA125', true, 'Correct. CA125 is the standard tumour marker used alongside ultrasound findings and menopausal status to calculate the Risk of Malignancy Index (RMI), which helps stratify women with an ovarian mass and guides referral to a specialist centre.', 5),
('ce000000-0000-0000-0000-000000000042', 'A', 'PSA can be elevated by benign conditions such as benign prostatic hyperplasia and prostatitis, as well as prostate cancer, limiting its specificity', true, 'Correct. PSA is organ-specific but not cancer-specific; it can be raised by BPH, prostatitis, urinary retention, and recent instrumentation, meaning an elevated result does not confirm cancer, and there is no formal UK national PSA screening programme.', 1),
('ce000000-0000-0000-0000-000000000042', 'B', 'PSA is highly specific for prostate cancer and a normal result excludes prostate cancer entirely', false, 'Ruled out because PSA is neither perfectly sensitive nor specific; some prostate cancers occur with a normal PSA.', 2),
('ce000000-0000-0000-0000-000000000042', 'C', 'The UK has a national PSA-based prostate cancer screening programme similar to breast and bowel screening', false, 'Ruled out because there is currently no national PSA screening programme in the UK; men can request an informed-choice PSA test after counselling.', 3),
('ce000000-0000-0000-0000-000000000042', 'D', 'PSA testing should be performed immediately after digital rectal examination or vigorous exercise for the most accurate result', false, 'Ruled out because recent DRE, ejaculation, vigorous exercise, and urinary infection can falsely elevate PSA, and testing should be deferred after these.', 4),
('ce000000-0000-0000-0000-000000000042', 'E', 'A normal PSA level means no further urological assessment is ever required regardless of symptoms', false, 'Ruled out because ongoing or new urological symptoms should still prompt assessment even with a normal PSA.', 5),
('ce000000-0000-0000-0000-000000000043', 'A', 'CA125', false, 'Ruled out because this is primarily used in ovarian cancer, not standard colorectal cancer surveillance.', 1),
('ce000000-0000-0000-0000-000000000043', 'B', 'Carcinoembryonic antigen (CEA)', true, 'Correct. CEA is the standard tumour marker used for surveillance monitoring after treatment for colorectal cancer; a rising CEA during follow-up raises suspicion of recurrence and prompts further imaging.', 2),
('ce000000-0000-0000-0000-000000000043', 'C', 'PSA', false, 'Ruled out because this is relevant to prostate pathology, not colorectal cancer monitoring.', 3),
('ce000000-0000-0000-0000-000000000043', 'D', 'AFP', false, 'Ruled out because this is relevant to hepatocellular carcinoma and germ cell tumours, not standard colorectal cancer surveillance.', 4),
('ce000000-0000-0000-0000-000000000043', 'E', 'CA19-9 alone as the primary marker', false, 'Ruled out because CA19-9 is more specific to pancreatic and biliary cancers and is not the standard first-line surveillance marker for colorectal cancer.', 5),
('ce000000-0000-0000-0000-000000000044', 'A', 'CA19-9', false, 'Ruled out because this is associated with pancreatic and biliary tract cancers, not the standard marker for HCC surveillance.', 1),
('ce000000-0000-0000-0000-000000000044', 'B', 'CA125', false, 'Ruled out because this is associated with ovarian cancer, not liver cancer surveillance.', 2),
('ce000000-0000-0000-0000-000000000044', 'C', 'PSA', false, 'Ruled out because this is relevant to prostate pathology, unrelated to liver cancer.', 3),
('ce000000-0000-0000-0000-000000000044', 'D', 'Alpha-fetoprotein (AFP)', true, 'Correct. AFP is the tumour marker used alongside 6-monthly liver ultrasound for surveillance of hepatocellular carcinoma in patients with cirrhosis or chronic hepatitis B, as a rising level can indicate the development of HCC.', 4),
('ce000000-0000-0000-0000-000000000044', 'E', 'CEA', false, 'Ruled out because this is primarily used in colorectal cancer surveillance, not the standard marker for HCC surveillance.', 5),
('ce000000-0000-0000-0000-000000000045', 'A', 'CA125', false, 'Ruled out because this is primarily associated with ovarian cancer, not the standard marker for pancreatic cancer.', 1),
('ce000000-0000-0000-0000-000000000045', 'B', 'PSA', false, 'Ruled out because this is relevant only to prostate pathology in men.', 2),
('ce000000-0000-0000-0000-000000000045', 'C', 'CA19-9', true, 'Correct. CA19-9 is the tumour marker most closely associated with pancreatic and biliary tract cancer, used to support the diagnosis alongside imaging/biopsy and as a baseline to monitor treatment response and detect recurrence.', 3),
('ce000000-0000-0000-0000-000000000045', 'D', 'Beta-hCG', false, 'Ruled out because this is relevant to germ cell tumours and gestational trophoblastic disease, not pancreatic cancer.', 4),
('ce000000-0000-0000-0000-000000000045', 'E', 'Calcitonin', false, 'Ruled out because this is used as a marker for medullary thyroid carcinoma, not pancreatic adenocarcinoma.', 5),
('ce000000-0000-0000-0000-000000000046', 'A', 'PSA alone', false, 'Ruled out because PSA is specific to prostate tissue and is not relevant to testicular germ cell tumours.', 1),
('ce000000-0000-0000-0000-000000000046', 'B', 'Beta-human chorionic gonadotropin (beta-hCG) and alpha-fetoprotein (AFP), alongside lactate dehydrogenase (LDH)', true, 'Correct. These markers are elevated in many testicular germ cell tumours, and baseline levels are essential for diagnosis, staging, and monitoring treatment response and recurrence.', 2),
('ce000000-0000-0000-0000-000000000046', 'C', 'CA125 alone', false, 'Ruled out because this is primarily relevant to ovarian cancer, not testicular tumours.', 3),
('ce000000-0000-0000-0000-000000000046', 'D', 'CEA alone', false, 'Ruled out because this is primarily associated with colorectal cancer, not the standard marker panel for testicular tumours.', 4),
('ce000000-0000-0000-0000-000000000046', 'E', 'CA19-9 alone', false, 'Ruled out because this is associated with pancreatic/biliary cancers, not the standard marker panel for testicular tumours.', 5),
('ce000000-0000-0000-0000-000000000047', 'A', 'CA125', false, 'Ruled out because this is primarily used for ovarian cancer, not the standard marker for breast cancer monitoring.', 1),
('ce000000-0000-0000-0000-000000000047', 'B', 'PSA', false, 'Ruled out because this is relevant only to prostate pathology.', 2),
('ce000000-0000-0000-0000-000000000047', 'C', 'CA15-3', true, 'Correct. CA15-3 is the tumour marker most commonly used to help monitor disease activity and treatment response in patients with known breast cancer, particularly metastatic disease, though it is not used for screening or diagnosis.', 3),
('ce000000-0000-0000-0000-000000000047', 'D', 'AFP', false, 'Ruled out because this is relevant to hepatocellular carcinoma and germ cell tumours, not breast cancer.', 4),
('ce000000-0000-0000-0000-000000000047', 'E', 'CA19-9', false, 'Ruled out because this is associated with pancreatic/biliary cancer, not the standard marker for breast cancer monitoring.', 5),
('ce000000-0000-0000-0000-000000000048', 'A', 'It is a one-off flexible sigmoidoscopy performed in all eligible adults regardless of test results', false, 'Ruled out because flexible sigmoidoscopy screening was a separate historical initiative and is not the current stool-based FIT screening pathway.', 1),
('ce000000-0000-0000-0000-000000000048', 'B', 'It is a blood test measuring CEA levels to detect colorectal cancer', false, 'Ruled out because CEA is not used as a population screening test due to insufficient sensitivity/specificity.', 2),
('ce000000-0000-0000-0000-000000000048', 'C', 'It requires no further action regardless of the result, as it is purely for research purposes', false, 'Ruled out because this is a clinical screening pathway with defined follow-up for positive results, not a research-only exercise.', 3),
('ce000000-0000-0000-0000-000000000048', 'D', 'It is a faecal immunochemical test (FIT) that detects trace amounts of blood in stool; an abnormal result leads to referral for colonoscopy', true, 'Correct. The NHS Bowel Cancer Screening Programme uses the FIT test, a home stool sample test detecting human haemoglobin, offered every 2 years to eligible adults; a positive result prompts referral for colonoscopy.', 4),
('ce000000-0000-0000-0000-000000000048', 'E', 'It involves a CT colonography for every participant as the primary screening tool', false, 'Ruled out because CT colonography is used as an alternative investigation in specific circumstances, not as the primary population screening test.', 5),
('ce000000-0000-0000-0000-000000000049', 'A', 'Screening mammography is offered annually from age 40 to all women', false, 'Ruled out because this is not the routine UK NHS screening interval or starting age for the general population.', 1),
('ce000000-0000-0000-0000-000000000049', 'B', 'Screening is performed using breast MRI for all women as the primary modality', false, 'Ruled out because mammography, not MRI, is the primary screening modality for the general population.', 2),
('ce000000-0000-0000-0000-000000000049', 'C', 'Screening stops permanently at age 60 for all women', false, 'Ruled out because routine invitations continue up to the 71st birthday, and women older than this can still request continued screening.', 3),
('ce000000-0000-0000-0000-000000000049', 'D', 'The programme uses ultrasound as the first-line screening test for all women', false, 'Ruled out because mammography, not ultrasound, is the first-line modality for population breast screening.', 4),
('ce000000-0000-0000-0000-000000000049', 'E', 'Routine mammography is offered every 3 years to women aged 50 up to their 71st birthday', true, 'Correct. The NHS Breast Screening Programme in England invites women for mammography every 3 years from age 50 up to their 71st birthday, with women over 71 able to self-refer to continue screening.', 5),
('ce000000-0000-0000-0000-000000000050', 'A', 'A cervical sample is tested first for high-risk human papillomavirus (HPV); cytology is only performed if HPV is detected, with screening offered every 3 years at her age', true, 'Correct. The NHS Cervical Screening Programme now uses primary HPV testing: samples are first tested for high-risk HPV, and only if positive is the sample also examined cytologically; women aged 25-49 are typically invited every 3 years, and those aged 50-64 every 5 years.', 1),
('ce000000-0000-0000-0000-000000000050', 'B', 'A Pap smear (cytology) is performed first on all samples, with HPV testing done only if cytology is abnormal', false, 'Ruled out because this describes the previous cytology-first approach; the current programme uses primary HPV testing first.', 2),
('ce000000-0000-0000-0000-000000000050', 'C', 'Screening is only offered to women who have never been vaccinated against HPV', false, 'Ruled out because screening is offered to all eligible women regardless of vaccination status, as the vaccine does not cover all high-risk HPV types.', 3),
('ce000000-0000-0000-0000-000000000050', 'D', 'Screening involves a blood test to detect HPV antibodies', false, 'Ruled out because cervical screening uses a cervical sample, not a blood test, to detect HPV directly from cervical cells.', 4),
('ce000000-0000-0000-0000-000000000050', 'E', 'Screening starts at age 40 in the UK', false, 'Ruled out because the NHS Cervical Screening Programme in England currently starts inviting women from age 25.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('ce000000-0000-0000-0000-000000000001', 'NICE NG12 recommends 2WW referral for suspected colorectal cancer in patients aged 40+ with unexplained weight loss and abdominal pain, aged 50+ with unexplained rectal bleeding, or aged 60+ with iron-deficiency anaemia or change in bowel habit.', 1),
('ce000000-0000-0000-0000-000000000001', 'A normal DRE does not exclude a more proximal colorectal cancer; red-flag symptom combinations warrant referral regardless of examination findings.', 2),
('ce000000-0000-0000-0000-000000000001', 'Iron-deficiency anaemia in an older adult should prompt investigation for GI blood loss before empirical iron replacement alone.', 3),
('ce000000-0000-0000-0000-000000000002', 'Any postmenopausal bleeding, even a single light episode, requires urgent (2WW) referral to exclude endometrial cancer.', 1),
('ce000000-0000-0000-0000-000000000002', 'Obesity, diabetes, and unopposed oestrogen exposure are major risk factors for endometrial cancer.', 2),
('ce000000-0000-0000-0000-000000000002', 'Transvaginal ultrasound (assessing endometrial thickness) is typically the first-line investigation, followed by biopsy/hysteroscopy if thickened.', 3),
('ce000000-0000-0000-0000-000000000003', 'Dysphagia at any age warrants urgent direct-access upper GI endoscopy (2WW) to exclude oesophageal or gastric cancer.', 1),
('ce000000-0000-0000-0000-000000000003', 'Progressive dysphagia (solids then liquids) suggests a mechanical, structural cause such as malignancy rather than a motility disorder.', 2),
('ce000000-0000-0000-0000-000000000003', 'Smoking and heavy alcohol use are major risk factors for oesophageal squamous cell carcinoma.', 3),
('ce000000-0000-0000-0000-000000000004', 'Unexplained visible haematuria in adults aged 45+ meets NICE NG12 criteria for urgent 2WW urological referral.', 1),
('ce000000-0000-0000-0000-000000000004', 'Painless visible haematuria should always be considered a red flag for urothelial malignancy until excluded.', 2),
('ce000000-0000-0000-0000-000000000004', 'Smoking is the single greatest modifiable risk factor for bladder cancer, even years after cessation.', 3),
('ce000000-0000-0000-0000-000000000005', 'A new, discrete, hard breast lump with irregular margins in a woman aged 30 or over meets criteria for urgent 2WW referral for triple assessment.', 1),
('ce000000-0000-0000-0000-000000000005', 'Triple assessment (clinical examination, imaging, biopsy/cytology) is the standard secondary care diagnostic pathway.', 2),
('ce000000-0000-0000-0000-000000000005', 'Absence of a family history does not lower the priority of referral for a clinically suspicious lump.', 3),
('ce000000-0000-0000-0000-000000000006', 'Persistent unexplained hoarseness for more than 3 weeks, particularly in smokers, requires urgent ENT referral (2WW) for laryngoscopy.', 1),
('ce000000-0000-0000-0000-000000000006', 'A chest X-ray should also be considered in this group but does not replace ENT referral.', 2),
('ce000000-0000-0000-0000-000000000006', 'A normal neck examination does not exclude early laryngeal malignancy, which is often only visible on direct laryngoscopy.', 3),
('ce000000-0000-0000-0000-000000000007', 'Unexplained iron-deficiency anaemia in men of any age, or in postmenopausal women, should prompt urgent 2WW referral for investigation of occult GI malignancy.', 1),
('ce000000-0000-0000-0000-000000000007', 'Colorectal cancer can present with iron-deficiency anaemia alone, particularly right-sided tumours, without a change in bowel habit.', 2),
('ce000000-0000-0000-0000-000000000007', 'A negative coeliac screen does not remove the need for endoscopic/colonoscopic investigation in this risk group.', 3),
('ce000000-0000-0000-0000-000000000008', 'A painless, firm, irregular intratesticular mass in a man of any age should be treated as suspicious for testicular cancer and referred urgently.', 1),
('ce000000-0000-0000-0000-000000000008', 'Testicular cancer is the most common malignancy in men aged 15-35 and often presents incidentally after minor trauma prompts self-examination.', 2),
('ce000000-0000-0000-0000-000000000008', 'Epididymo-orchitis typically causes a tender, inflamed testis with systemic/urinary symptoms, helping distinguish it clinically, though ultrasound is required in equivocal cases.', 3),
('ce000000-0000-0000-0000-000000000009', 'The weighted 7-point checklist (major features: change in size, irregular shape, irregular colour; minor features: diameter >=7mm, inflammation, oozing, altered sensation) helps identify lesions needing urgent referral.', 1),
('ce000000-0000-0000-0000-000000000009', 'Suspected melanoma should be referred via the 2WW pathway for excision biopsy by a specialist, not partial/shave biopsy in primary care.', 2),
('ce000000-0000-0000-0000-000000000009', 'Absence of a family history does not lower suspicion when clinical (ABCDE) features are concerning.', 3),
('ce000000-0000-0000-0000-000000000010', 'Unexplained haemoptysis in anyone aged 40 or over should prompt an urgent chest X-ray (within 2 weeks) as per NICE NG12.', 1),
('ce000000-0000-0000-0000-000000000010', 'A normal clinical chest examination does not exclude lung cancer; many early lung cancers are asymptomatic on examination.', 2),
('ce000000-0000-0000-0000-000000000010', 'Heavy smoking history combined with weight loss and haemoptysis substantially raises pre-test probability and lowers the threshold for urgent referral.', 3),
('ce000000-0000-0000-0000-000000000011', 'Anthracyclines (doxorubicin, epirubicin) cause cumulative, dose-dependent cardiotoxicity (dilated cardiomyopathy/heart failure); baseline and periodic LVEF monitoring is essential.', 1),
('ce000000-0000-0000-0000-000000000011', 'Cardiotoxicity risk increases with cumulative dose, pre-existing cardiac disease, hypertension, and concurrent trastuzumab or mediastinal radiotherapy.', 2),
('ce000000-0000-0000-0000-000000000011', 'Anthracycline cardiac damage can be irreversible, unlike some other chemotherapy toxicities, making pre-treatment risk assessment important.', 3),
('ce000000-0000-0000-0000-000000000012', $x$Cisplatin's dose-limiting toxicities are nephrotoxicity (proximal tubular injury) and ototoxicity; nephrotoxicity risk is reduced by aggressive peri-treatment IV hydration.$x$, 1),
('ce000000-0000-0000-0000-000000000012', 'Renal function must be checked before each cisplatin cycle, with dose adjustment or substitution (e.g., carboplatin) in renal impairment.', 2),
('ce000000-0000-0000-0000-000000000012', 'Ototoxicity from cisplatin is typically irreversible and monitored separately; hydration specifically targets renal, not auditory, toxicity.', 3),
('ce000000-0000-0000-0000-000000000013', 'Vincristine causes a dose-limiting peripheral neuropathy, typically sensorimotor, with distal weakness, paraesthesia, and loss of ankle reflexes; severe cases can affect autonomic function (e.g., constipation, ileus).', 1),
('ce000000-0000-0000-0000-000000000013', 'Vincristine is a potent vesicant and is fatal if given intrathecally by error, so strict administration protocols exist.', 2),
('ce000000-0000-0000-0000-000000000013', 'Neuropathy severity may require dose reduction or delay; it can partially or fully resolve after stopping treatment, though recovery may be slow.', 3),
('ce000000-0000-0000-0000-000000000014', 'Bleomycin causes dose-dependent pulmonary fibrosis; patients who have received it should have inspired oxygen concentrations minimised during anaesthesia, even years after treatment, as high FiO2 can precipitate acute lung injury.', 1),
('ce000000-0000-0000-0000-000000000014', 'Baseline and interval pulmonary function tests (including DLCO) are used to monitor for bleomycin toxicity during treatment.', 2),
('ce000000-0000-0000-0000-000000000014', 'Risk of bleomycin lung toxicity increases with cumulative dose, older age, renal impairment, and concurrent or prior chest radiotherapy.', 3),
('ce000000-0000-0000-0000-000000000015', 'Hand-foot syndrome is a common toxicity of fluoropyrimidines (capecitabine, 5-fluorouracil) and some targeted agents, presenting with painful, symmetrical erythema and desquamation of palms/soles.', 1),
('ce000000-0000-0000-0000-000000000015', 'Management includes dose interruption or reduction, emollients, and analgesia; severe cases may require stopping the drug.', 2),
('ce000000-0000-0000-0000-000000000015', 'It should be distinguished from infection (asymmetrical, febrile, systemically unwell) and from other dermatological chemotherapy toxicities such as EGFR-inhibitor acneiform rash.', 3),
('ce000000-0000-0000-0000-000000000016', 'Tamoxifen acts as an oestrogen antagonist in breast tissue but as an oestrogen agonist in the endometrium, increasing the risk of endometrial hyperplasia and cancer.', 1),
('ce000000-0000-0000-0000-000000000016', 'Tamoxifen also increases venous thromboembolism risk, which should be considered in any patient presenting with symptoms of DVT/PE while on treatment.', 2),
('ce000000-0000-0000-0000-000000000016', 'Any postmenopausal bleeding in a patient on tamoxifen must be urgently investigated regardless of how long they have been on treatment.', 3),
('ce000000-0000-0000-0000-000000000017', 'Trastuzumab causes cardiotoxicity, typically a reversible decline in LVEF, distinct from the often irreversible cardiomyopathy seen with anthracyclines.', 1),
('ce000000-0000-0000-0000-000000000017', 'Cardiotoxicity risk is increased with prior or concurrent anthracycline use, so sequencing and monitoring (baseline and 3-monthly echocardiograms) are important.', 2),
('ce000000-0000-0000-0000-000000000017', 'Treatment is often paused or stopped if LVEF drops significantly, with cardiology input, and can frequently be resumed once function recovers.', 3),
('ce000000-0000-0000-0000-000000000018', 'Folinic acid ("leucovorin rescue") is given after high-dose methotrexate to reduce toxicity to normal cells while methotrexate continues to act preferentially on rapidly dividing tumour cells.', 1),
('ce000000-0000-0000-0000-000000000018', 'Methotrexate is renally excreted; adequate hydration, urine alkalinisation, and monitoring of renal function and methotrexate levels are essential to prevent toxic accumulation.', 2),
('ce000000-0000-0000-0000-000000000018', 'Key toxicities of methotrexate include myelosuppression, mucositis, and nephrotoxicity; concurrent NSAIDs can dangerously increase methotrexate levels and should be avoided.', 3),
('ce000000-0000-0000-0000-000000000019', 'Immune checkpoint inhibitors (e.g., pembrolizumab, nivolumab, ipilimumab) can cause immune-related adverse events in any organ system, including colitis, pneumonitis, hepatitis, endocrinopathies, and skin toxicity.', 1),
('ce000000-0000-0000-0000-000000000019', 'Immune-related colitis is managed with corticosteroids and, if severe or steroid-refractory, biologic agents (e.g., infliximab); the causative drug is often withheld or discontinued depending on severity.', 2),
('ce000000-0000-0000-0000-000000000019', 'Symptoms of immune-related toxicity can occur at any point during treatment, including weeks to months after the last dose, so a high index of suspicion is needed.', 3),
('ce000000-0000-0000-0000-000000000020', 'Vesicant chemotherapy agents (e.g., vinca alkaloids, anthracyclines) can cause severe local tissue damage, ulceration, and necrosis if they extravasate outside the vein.', 1),
('ce000000-0000-0000-0000-000000000020', 'Suspected extravasation requires immediate cessation of the infusion, aspiration of residual drug, limb elevation, and following the specific local extravasation protocol.', 2),
('ce000000-0000-0000-0000-000000000020', 'Early recognition (pain, swelling, erythema, loss of blood return) and prompt action reduce the risk of long-term tissue damage; delayed treatment can necessitate surgical debridement.', 3),
('ce000000-0000-0000-0000-000000000021', $x$Peau d'orange skin change results from dermal lymphatic oedema secondary to tumour infiltration and is a red flag for underlying (often locally advanced or inflammatory) breast cancer.$x$, 1),
('ce000000-0000-0000-0000-000000000021', $x$Nipple retraction and skin tethering occur when tumour infiltrates and shortens the suspensory (Cooper's) ligaments, even without a clearly palpable mass.$x$, 2),
('ce000000-0000-0000-0000-000000000021', 'All patients with suspicious skin or nipple changes require urgent 2WW referral for triple assessment, regardless of whether a discrete lump is felt.', 3),
('ce000000-0000-0000-0000-000000000022', $x$Pancoast (superior sulcus) tumours arise at the lung apex and can invade the brachial plexus and the sympathetic chain, causing Horner's syndrome: ptosis, miosis, anhidrosis.$x$, 1),
('ce000000-0000-0000-0000-000000000022', 'Finger clubbing is a recognised paraneoplastic feature of lung cancer and other chronic lung/cardiac conditions.', 2),
('ce000000-0000-0000-0000-000000000022', $x$Any new Horner's syndrome, especially with a smoking history, warrants imaging (CT chest) to exclude an apical lung tumour.$x$, 3),
('ce000000-0000-0000-0000-000000000023', 'Left-sided colorectal tumours more often cause obstructive symptoms (altered bowel habit, tenesmus, PR bleeding), while right-sided tumours more often present with occult blood loss and anaemia.', 1),
('ce000000-0000-0000-0000-000000000023', 'Any combination of change in bowel habit, PR bleeding, and unintentional weight loss in an older adult requires urgent 2WW referral for colonoscopy regardless of examination findings.', 2),
('ce000000-0000-0000-0000-000000000023', 'Benign diagnoses such as haemorrhoids or diverticular disease should not be assumed without colonic investigation when red-flag features are present.', 3),
('ce000000-0000-0000-0000-000000000024', 'Prostate cancer has a strong predilection for metastasising to bone, especially the axial skeleton, often causing sclerotic lesions and can present with pain before urinary symptoms are prominent.', 1),
('ce000000-0000-0000-0000-000000000024', 'A markedly elevated PSA combined with an asymmetrical, hard, nodular prostate on examination is highly suspicious for prostate cancer and warrants urgent urological referral.', 2),
('ce000000-0000-0000-0000-000000000024', 'New back pain in a patient with known or suspected prostate cancer should always raise concern for spinal metastases and, if neurological symptoms develop, for possible metastatic spinal cord compression.', 3),
('ce000000-0000-0000-0000-000000000025', 'New dyspepsia combined with weight loss, vomiting, dysphagia, or an abdominal mass, particularly in patients over 55, is a red-flag presentation requiring urgent (2WW) upper GI endoscopy.', 1),
('ce000000-0000-0000-0000-000000000025', 'Gastric cancer often presents insidiously with vague upper GI symptoms, and by the time weight loss occurs, disease may already be locally advanced.', 2),
('ce000000-0000-0000-0000-000000000025', 'H. pylori testing and treatment is appropriate in uncomplicated dyspepsia but should not delay urgent endoscopy when alarm features are present.', 3),
('ce000000-0000-0000-0000-000000000026', $x$Courvoisier's law: painless jaundice with a palpable gallbladder is unlikely to be due to gallstones and is more likely a malignant obstruction, classically pancreatic head cancer.$x$, 1),
('ce000000-0000-0000-0000-000000000026', 'Painless progressive jaundice with pale stools, dark urine, and pruritus indicates an obstructive pattern, requiring urgent imaging to identify the level and cause of obstruction.', 2),
('ce000000-0000-0000-0000-000000000026', 'Pancreatic head tumours present earlier with jaundice due to biliary obstruction, whereas body/tail tumours present later with pain and weight loss.', 3),
('ce000000-0000-0000-0000-000000000027', 'Ovarian cancer classically presents with vague, non-specific symptoms (bloating, early satiety, pelvic/abdominal pain, urinary frequency), often leading to delayed diagnosis.', 1),
('ce000000-0000-0000-0000-000000000027', 'NICE guidance recommends measuring serum CA125 in women (especially aged 50+) with these symptoms; if elevated, ultrasound and urgent referral should follow.', 2),
('ce000000-0000-0000-0000-000000000027', 'New IBS-type symptoms in a woman over 50 without a previous IBS diagnosis should prompt investigation for ovarian cancer before an IBS diagnosis is made.', 3),
('ce000000-0000-0000-0000-000000000028', 'Renal cell carcinoma classically presents with a triad of haematuria, flank pain, and a palpable mass, though all three together occur in only a minority of patients.', 1),
('ce000000-0000-0000-0000-000000000028', 'A left-sided varicocele that persists when lying flat suggests obstruction of the left testicular vein where it drains into the left renal vein, which can occur with renal tumour extension.', 2),
('ce000000-0000-0000-0000-000000000028', 'Painless visible haematuria in an adult should always prompt urgent urological referral and imaging to exclude renal, ureteric, or bladder malignancy.', 3),
('ce000000-0000-0000-0000-000000000029', 'Painless visible haematuria in an adult, particularly aged 45 or older, should always be investigated urgently to exclude urothelial malignancy.', 1),
('ce000000-0000-0000-0000-000000000029', 'Occupational exposure to aromatic amines (dye, rubber, chemical industries) and smoking are major risk factors for bladder cancer.', 2),
('ce000000-0000-0000-0000-000000000029', 'Investigation typically includes urgent cystoscopy and upper tract imaging, as cystoscopy alone will not detect upper tract urothelial tumours.', 3),
('ce000000-0000-0000-0000-000000000030', 'A firm, fixed, painless cervical lymph node persisting for more than 3 weeks in an adult, especially with risk factors or an associated mucosal lesion, should be urgently investigated for head and neck malignancy.', 1),
('ce000000-0000-0000-0000-000000000030', 'Oropharyngeal squamous cell carcinoma commonly presents with a visible or palpable ulcerated lesion, dysphagia, referred otalgia, and cervical lymphadenopathy; HPV-related disease is increasingly common even in non-smokers.', 2),
('ce000000-0000-0000-0000-000000000030', 'Any unexplained neck lump persisting beyond 3-4 weeks warrants urgent 2WW ENT referral for examination and imaging/biopsy.', 3),
('ce000000-0000-0000-0000-000000000031', 'Neutropenic sepsis is defined as a neutrophil count <0.5 x10^9/L with fever >=38C (or signs of sepsis) in a patient who has recently received chemotherapy; it is a medical emergency.', 1),
('ce000000-0000-0000-0000-000000000031', 'Empirical broad-spectrum IV antibiotics must be given within 1 hour of presentation, before microbiology results are available.', 2),
('ce000000-0000-0000-0000-000000000031', 'Any patient who has received chemotherapy in the preceding 6 weeks presenting with fever should have neutropenic sepsis considered and an FBC checked urgently.', 3),
('ce000000-0000-0000-0000-000000000032', 'Metastatic spinal cord compression should be suspected in any patient with known or suspected cancer who develops new back pain with neurological symptoms/signs and is a time-critical oncological emergency.', 1),
('ce000000-0000-0000-0000-000000000032', 'Immediate high-dose corticosteroids should be given as soon as MSCC is suspected, without waiting for imaging, to reduce cord oedema and preserve neurological function.', 2),
('ce000000-0000-0000-0000-000000000032', 'Whole-spine MRI is needed within 24 hours as multiple levels of compression are common; definitive treatment options include urgent radiotherapy or surgical decompression.', 3),
('ce000000-0000-0000-0000-000000000033', 'SVCO is most commonly caused by extrinsic compression from mediastinal malignancy, particularly lung cancer (especially small cell) and lymphoma, and is an oncological emergency.', 1),
('ce000000-0000-0000-0000-000000000033', 'Classic features include facial and upper limb swelling/plethora, distended non-pulsatile neck veins, dilated collateral chest wall veins, and headache/visual disturbance worse on bending forward or lying flat.', 2),
('ce000000-0000-0000-0000-000000000033', 'Management includes sitting the patient upright, urgent CT chest with contrast, and depending on cause and severity, corticosteroids, stenting, radiotherapy, or chemotherapy; tissue diagnosis should be sought where possible before irradiating.', 3),
('ce000000-0000-0000-0000-000000000034', 'Tumour lysis syndrome occurs when rapid destruction of malignant cells releases intracellular potassium, phosphate, and nucleic acids (metabolised to uric acid), causing hyperkalaemia, hyperphosphataemia, hyperuricaemia, and secondary hypocalcaemia, with risk of acute kidney injury and arrhythmia.', 1),
('ce000000-0000-0000-0000-000000000034', 'It is most common with high-grade, rapidly proliferating, bulky haematological malignancies and is anticipated with prophylactic measures (aggressive IV hydration, allopurinol or rasburicase, cardiac monitoring) in high-risk patients.', 2),
('ce000000-0000-0000-0000-000000000034', 'Hyperkalaemia is the most immediately life-threatening abnormality and should be treated urgently; rasburicase is used for established hyperuricaemia, while dialysis may be needed in severe or refractory cases.', 3),
('ce000000-0000-0000-0000-000000000035', 'Hypercalcaemia of malignancy is most commonly due to bone metastases causing local osteolysis or humoral mechanisms (PTHrP secretion), and presents with confusion, polyuria/polydipsia, nausea, constipation, and in severe cases coma or arrhythmia.', 1),
('ce000000-0000-0000-0000-000000000035', 'First-line management is aggressive IV rehydration with 0.9% saline followed by an IV bisphosphonate, which takes 2-4 days for full effect; ECG monitoring is important given arrhythmia risk.', 2),
('ce000000-0000-0000-0000-000000000035', 'Hypercalcaemia should be actively considered in any confused or drowsy patient with known malignancy and treated urgently, as it is often reversible with prompt therapy.', 3),
('ce000000-0000-0000-0000-000000000036', 'Brain metastases cause symptoms via mass effect and surrounding vasogenic oedema; corticosteroids are the mainstay of rapid symptomatic treatment.', 1),
('ce000000-0000-0000-0000-000000000036', 'Symptoms and signs of raised intracranial pressure include early-morning headache, vomiting, papilloedema, and focal neurological deficits depending on lesion location.', 2),
('ce000000-0000-0000-0000-000000000036', 'Lumbar puncture is contraindicated in the presence of a space-occupying lesion/raised ICP due to the risk of precipitating tonsillar or transtentorial herniation.', 3),
('ce000000-0000-0000-0000-000000000037', 'Massive haemoptysis is a medical emergency where the immediate risk is asphyxiation from blood flooding the airway; airway protection and positioning to prevent aspiration into the unaffected lung are priorities.', 1),
('ce000000-0000-0000-0000-000000000037', 'Management requires urgent multidisciplinary involvement (anaesthetics, respiratory medicine, interventional radiology for bronchial artery embolisation, and/or thoracic surgery), alongside resuscitation.', 2),
('ce000000-0000-0000-0000-000000000037', 'Malignancy (especially squamous cell lung cancer, which can erode into major vessels) and prior radiotherapy are recognised risk factors for massive, life-threatening haemoptysis.', 3),
('ce000000-0000-0000-0000-000000000038', 'Any patient who has received chemotherapy within the preceding 6 weeks and develops a temperature of 38C or above must be assessed as an emergency for possible neutropenic sepsis, with an urgent FBC.', 1),
('ce000000-0000-0000-0000-000000000038', 'Delay in recognition and treatment of neutropenic sepsis significantly increases mortality; patients are typically given written safety information and a 24-hour oncology contact number.', 2),
('ce000000-0000-0000-0000-000000000038', 'If neutropenic sepsis is confirmed, empirical broad-spectrum IV antibiotics must be given within 1 hour of hospital arrival.', 3),
('ce000000-0000-0000-0000-000000000039', 'Small cell lung cancer is a well-recognised paraneoplastic cause of SIADH, due to ectopic ADH secretion by tumour cells, leading to euvolaemic hyponatraemia.', 1),
('ce000000-0000-0000-0000-000000000039', 'SIADH is characterised by hyponatraemia with low plasma osmolality, inappropriately concentrated urine, and clinical euvolaemia.', 2),
('ce000000-0000-0000-0000-000000000039', 'Management includes fluid restriction as first-line and treatment of the underlying malignancy; overly rapid correction risks osmotic demyelination syndrome.', 3),
('ce000000-0000-0000-0000-000000000040', 'Malignant bowel obstruction in patients with advanced intra-abdominal malignancy is initially managed conservatively with NG tube decompression, IV fluids, and correction of electrolyte imbalances, while a multidisciplinary decision is made.', 1),
('ce000000-0000-0000-0000-000000000040', 'Not all patients with malignant bowel obstruction are suitable for surgery; the decision depends on extent of disease, performance status, and number of obstruction points, and should involve senior surgical and oncology/palliative input.', 2),
('ce000000-0000-0000-0000-000000000040', 'If surgery or stenting is not appropriate, symptom control with antiemetics, analgesia, and antisecretory agents forms the basis of palliative medical management.', 3),
('ce000000-0000-0000-0000-000000000041', 'The Risk of Malignancy Index (RMI) combines serum CA125, ultrasound findings, and menopausal status to estimate the probability of ovarian malignancy and guide specialist referral.', 1),
('ce000000-0000-0000-0000-000000000041', 'CA125 is not specific to ovarian cancer and can be raised in other conditions (endometriosis, fibroids, pelvic infection), so must be interpreted alongside imaging and clinical findings.', 2),
('ce000000-0000-0000-0000-000000000041', 'In younger women with a complex ovarian mass, additional markers (AFP, beta-hCG, LDH) may be checked to help identify germ cell tumours, which are more common in this age group.', 3),
('ce000000-0000-0000-0000-000000000042', 'There is no national UK screening programme for prostate cancer using PSA, because of concerns about limited specificity/sensitivity leading to overdiagnosis and overtreatment; men over 50 can request an informed-choice PSA test.', 1),
('ce000000-0000-0000-0000-000000000042', 'PSA can be raised by benign prostatic hyperplasia, prostatitis, urinary retention, and instrumentation, as well as prostate cancer, so an elevated result requires further assessment rather than being diagnostic alone.', 2),
('ce000000-0000-0000-0000-000000000042', 'Recent ejaculation, vigorous exercise, digital rectal examination, and urinary infection can transiently raise PSA and should be avoided or accounted for before testing.', 3),
('ce000000-0000-0000-0000-000000000043', 'CEA is used for post-treatment surveillance in colorectal cancer to help detect recurrence early, but it is not sensitive or specific enough to be used as a screening or diagnostic test.', 1),
('ce000000-0000-0000-0000-000000000043', 'A rising CEA during follow-up should prompt further investigation to look for recurrent or metastatic disease, most commonly in the liver.', 2),
('ce000000-0000-0000-0000-000000000043', 'CEA can also be elevated by benign conditions (smoking, inflammatory bowel disease), so results must be interpreted in clinical context, and a normal CEA does not exclude recurrence.', 3),
('ce000000-0000-0000-0000-000000000044', 'AFP is also markedly elevated in certain germ cell tumours, so it has utility beyond hepatocellular carcinoma surveillance.', 1),
('ce000000-0000-0000-0000-000000000044', 'HCC surveillance in high-risk groups typically combines 6-monthly liver ultrasound with AFP measurement, as either alone has lower sensitivity than the combination.', 2),
('ce000000-0000-0000-0000-000000000044', 'AFP can also be mildly elevated in pregnancy and some benign liver conditions, so results should be interpreted alongside imaging rather than in isolation.', 3),
('ce000000-0000-0000-0000-000000000045', 'CA19-9 is most strongly associated with pancreatic and biliary tract malignancy and is used to aid diagnosis, monitor treatment response, and detect recurrence, but is not diagnostic alone.', 1),
('ce000000-0000-0000-0000-000000000045', 'CA19-9 can be falsely low in patients who lack the Lewis antigen, and can also be elevated in benign biliary obstruction/cholangitis, limiting its specificity.', 2),
('ce000000-0000-0000-0000-000000000045', 'Tissue diagnosis remains necessary to confirm pancreatic cancer; CA19-9 supports but does not replace histological confirmation.', 3),
('ce000000-0000-0000-0000-000000000046', 'Beta-hCG, AFP, and LDH form the standard tumour marker panel for testicular germ cell tumours, used at diagnosis, for staging, and for monitoring response to treatment and detecting relapse.', 1),
('ce000000-0000-0000-0000-000000000046', 'Seminomas may have a mildly raised beta-hCG but a normal AFP, whereas non-seminomatous germ cell tumours more frequently raise AFP and/or beta-hCG substantially.', 2),
('ce000000-0000-0000-0000-000000000046', 'Marker levels that fail to normalise as expected after orchidectomy, based on their known half-lives, suggest residual or metastatic disease requiring further treatment.', 3),
('ce000000-0000-0000-0000-000000000047', 'CA15-3 is used to help monitor known breast cancer, particularly metastatic disease, alongside clinical assessment and imaging, but lacks the sensitivity and specificity for screening or diagnosis.', 1),
('ce000000-0000-0000-0000-000000000047', 'Breast cancer screening in the UK is based on mammography via the NHS Breast Screening Programme, not tumour marker testing.', 2),
('ce000000-0000-0000-0000-000000000047', 'A rising CA15-3 in a patient on treatment may suggest disease progression, but results should always be interpreted alongside clinical and radiological findings.', 3),
('ce000000-0000-0000-0000-000000000048', 'The NHS Bowel Cancer Screening Programme uses the faecal immunochemical test (FIT), a home-based stool sample test detecting human haemoglobin, generally offered every 2 years to eligible adults.', 1),
('ce000000-0000-0000-0000-000000000048', 'A positive FIT result leads to referral for colonoscopy to look for the source of blood loss, which may be a polyp, cancer, or other benign cause.', 2),
('ce000000-0000-0000-0000-000000000048', 'Anyone with symptoms suggestive of colorectal cancer should be referred symptomatically regardless of screening status or results, not wait for their next screening round.', 3),
('ce000000-0000-0000-0000-000000000049', 'The NHS Breast Screening Programme in England routinely invites women for mammography every 3 years from age 50 up to their 71st birthday; women older than this can self-refer to continue.', 1),
('ce000000-0000-0000-0000-000000000049', 'Women at significantly increased risk may be offered earlier and more frequent surveillance, sometimes including MRI, outside the standard population programme.', 2),
('ce000000-0000-0000-0000-000000000049', 'Any woman with a new breast symptom should be referred via the symptomatic 2WW pathway rather than waiting for a screening appointment.', 3),
('ce000000-0000-0000-0000-000000000050', 'The NHS Cervical Screening Programme uses primary HPV testing: a cervical sample is tested first for high-risk HPV, and cytology is only performed on HPV-positive samples.', 1),
('ce000000-0000-0000-0000-000000000050', 'In England, screening is generally offered from age 25 to 49 every 3 years, and from age 50 to 64 every 5 years, with HPV-negative results returning to routine recall.', 2),
('ce000000-0000-0000-0000-000000000050', 'Cervical screening is still recommended for women who have received the HPV vaccine, as current vaccines do not cover all high-risk HPV types.', 3);
